<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {chooseCompany} from '../payrollUi'
import type {PayrollHomeData,SalaryTemplate} from '../payrollTypes'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),router=useRouter(),{api,r,t,english,home,base,loading,failure,load}=usePayrollPage(),company=ref(''),companies=ref<PayrollHomeData['companies']>([]),items=ref<SalaryTemplate[]>([])
function refresh(){items.value=[];void load(()=>{const c=chooseCompany({companies:companies.value},company.value);return api().get<SalaryTemplate[]>('/salary-templates?companyId='+encodeURIComponent(c))},v=>items.value=v)}
function changeCompany(){void router.replace({query:{...route.query,companyId:company.value}});refresh()}
onMounted(async()=>{await load(()=>api().get<PayrollHomeData>('/payroll-home'),h=>{company.value=chooseCompany(h,String(route.query.companyId||''));companies.value=h.companies});if(company.value)refresh()})
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{r('templates')}}</h2><RouterLink v-if="company&&(home?.employeeManage||home?.headOffice)" class="wf-button primary" :to="{path:base+'/pay-template-library',query:{companyId:company}}">{{english()?'Template library / publication':'模板库／发布母版'}}</RouterLink></header><div v-if="companies.length" class="wf-filters"><label>{{r('company')}}<select v-model="company" @change="changeCompany"><option v-for="c in companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div><PhaseStatus :failure="failure" :loading="loading"/><div v-if="company&&!loading" class="wf-table-wrap"><table><thead><tr><th>{{r('name')}}</th><th>{{r('basis')}}</th><th>{{r('rate')}}</th><th>{{t('status')}}</th><th></th></tr></thead><tbody><tr v-for="s in items" :key="s.id"><td>{{s.name}}</td><td>{{r(s.rule.basis)}}</td><td>{{s.rule.rate}}</td><td>{{r(s.enabled?'enabled':'disabled')}}</td><td><RouterLink :to="{path:base+'/salary-templates/'+s.id,query:{companyId:company}}">{{s.governanceSource?(english()?'View fixed version':'查看固定版本'):(english()?'View legacy template':'查看旧共享模板')}}</RouterLink></td></tr><tr v-if="!items.length"><td colspan="5" class="wf-empty">{{t('empty')}}</td></tr></tbody></table></div><p v-if="company&&!loading&&!failure&&!items.length" class="wf-hint">{{english()?'No templates for this company yet. Ask head office to publish a master, then an authorised store manager can preview and enable it.':'本公司尚无工资模板。请由总部发布母版，再由门店管理员预览并启用。'}}</p><p class="wf-hint">{{english()?'This page lists available rules and historical shared templates. View a version to inspect details; use the template library to publish or enable.':'本页汇总可用规则与历史共享模板。点击版本查看明细；发布或启用在模板库办理。'}} {{r('templateHint')}}</p></section></template>
